const listCIEvents = `-- name: ListCIEvents :many
SELECT account_id, run_id, sequence, event_type, created_at FROM ci_run_events WHERE account_id = $1 AND run_id = $2 ORDER BY sequence LIMIT $3::integer
`

type ListCIEventsParams struct {
	AccountID pgtype.UUID
	RunID     pgtype.UUID
	MaxRows   int32
}

func (q *Queries) ListCIEvents(ctx context.Context, db DBTX, arg ListCIEventsParams) ([]CiRunEvent, error) {
	rows, err := db.Query(ctx, listCIEvents, arg.AccountID, arg.RunID, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CiRunEvent{}
	for rows.Next() {
		var i CiRunEvent
		if err := rows.Scan(
			&i.AccountID,
			&i.RunID,
			&i.Sequence,
			&i.EventType,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

